const allowedTags = new Set(['[excited]', '[angry]', '[sad]', '[surprised]', '[sigh]', '[chuckle]', '[laughing]', '[short pause]', '[pause]', '[whisper]', '[emphasis]', '[professional broadcast tone]']);

return items.map((item) => {
  const script = item.json.script_text;
  const plan = item.json.production_response;
  if (typeof script !== 'string' || !script) throw new Error('The approved creative narration is missing.');
  if (!plan || plan.status !== 'READY' || !Array.isArray(plan.beats) || plan.beats.length === 0) throw new Error('The Production Plan is not READY or has no beats.');

  const beatText = plan.beats.map((beat) => {
    if (!beat || typeof beat.spoken_text !== 'string') throw new Error('Every beat requires spoken_text.');
    return beat.spoken_text;
  }).join('');
  if (beatText !== script) throw new Error('Production beats do not reconstruct the approved narration exactly.');

  const insertions = [];
  let beatOffset = 0;
  for (const beat of plan.beats) {
    const tags = beat.voice?.fish_tags ?? [];
    if (!Array.isArray(tags)) throw new Error('fish_tags must be an array.');
    for (let order = 0; order < tags.length; order += 1) {
      const control = tags[order];
      if (!allowedTags.has(control.tag)) throw new Error(`Fish tag is not allowed: ${control.tag}`);
      if (!['before', 'after'].includes(control.position)) throw new Error(`Invalid Fish tag position: ${control.position}`);
      if (typeof control.anchor_text !== 'string' || !control.anchor_text) throw new Error('Fish tag anchor_text is required.');
      const localOffset = beat.spoken_text.indexOf(control.anchor_text);
      if (localOffset < 0) throw new Error(`Fish tag anchor was not found: ${control.anchor_text}`);
      insertions.push({ offset: beatOffset + localOffset + (control.position === 'after' ? control.anchor_text.length : 0), tag: control.tag, order });
    }
    beatOffset += beat.spoken_text.length;
  }

  let compiled = script;
  for (const insertion of insertions.sort((a, b) => b.offset - a.offset || b.order - a.order)) {
    compiled = `${compiled.slice(0, insertion.offset)}${insertion.tag}${compiled.slice(insertion.offset)}`;
  }
  const scriptId = String(item.json.script_id);
  const executionId = String($execution.id);
  return {
    json: {
      ...item.json,
      compiled_text: compiled,
      audio_uri: `/n8n-youtube-automation/Honi-News/Audio/${scriptId}-${executionId}.wav`,
      adapter_request: { script_id: scriptId, text: compiled, voice_id: 'honi', format: 'wav' }
    }
  };
});
